 bool CHackingAbilityLineShift::CanActivate()
 {
 const CHackingGameboard& gameboard = m_hackingSession.GetGameboard();
 if (m_owner.GetSpareNodeId() == INVALID_NODE_ID || gameboard.IsNodeRotating(m_owner.GetSpareNodeId()) || !gameboard.CanShiftLine(m_targetLine, m_shiftDir, m_params.chargeUpTime))
 {
 return false;
 }

 return CHackingAbilityBase::CanActivate();
 }

 ////////////////////////////////////////////////////////////////////////////
 bool CHackingAbilityLineShift::TryActivate()
 {
 const float shiftRate = m_params.duration > 0.0f ? (1.0f / m_params.duration) : 0.0f;
 if (CanActivate() && m_hackingSession.GetGameboard().StartLineShift(m_owner.GetId(), m_shiftDir, m_targetLine, m_owner.GetSpareNodeId(), m_params.chargeUpTime, shiftRate))
 {
 Activate();
 return true;
 }

 return false;
 }

 /////////////////////////////////////////////////////////////////////////
 void CHackingAbilityLineShift::HandleEvent(const SHackingEvtBase& evt)
 {
 switch (evt.type)
 {
 case EHackingEvtType::PC_InsertedNodeRotationRequested:
 {
 CHackingGameboard& gameboard = m_hackingSession.GetGameboard();
 const SHackingEvt_PlayerControlInsertedNodeRotationRequested controlEvt = static_cast<const SHackingEvt_PlayerControlInsertedNodeRotationRequested&>(evt);
 if (m_owner.GetSpareNodeId() != INVALID_NODE_ID && controlEvt.agentId == m_owner.GetId() && !gameboard.IsNodeRotating(m_owner.GetSpareNodeId()) && 
 m_currentState != EHackingAbilityState::Active && m_currentState != EHackingAbilityState::ChargeUp)
 {
 gameboard.StartNodeRotation(m_owner.GetSpareNodeId(), controlEvt.bRotateClockwise, NODE_ROTATION_RATE);
 }

 break;
 }

 case EHackingEvtType::LineShiftStatusChanged:
 {
 CHackingGameboard& gameboard = m_hackingSession.GetGameboard();
 const SHackingEvt_LineShiftStatusChanged lineShiftEvt = static_cast<const SHackingEvt_LineShiftStatusChanged&>(evt);
 if (m_owner.GetSpareNodeId() != INVALID_NODE_ID && m_owner.GetSpareNodeId() == lineShiftEvt.insertedNodeId)
 {
 if (lineShiftEvt.IsShiftStarting() && GetAbilityState() != EHackingAbilityState::Active)
 {
 SwitchToState(EHackingAbilityState::Active);
 }
 else if (!lineShiftEvt.IsShiftStarting())
 {
 m_owner.SetSpareNodeId(lineShiftEvt.removedNodeId);
 if (GetAbilityState() != EHackingAbilityState::Cooldown)
 {
 SwitchToState(EHackingAbilityState::Cooldown);
 }
 }
 }
 break;
 }
 }
 }

 ///////////////////////////////////////////////////////////////////////////
 void CHackingAbilityLineShift::SetTarget(const uint16 targetLine, const EPathPatternType shiftDir)
 {
 m_targetLine = targetLine;
 m_shiftDir = shiftDir;
 }
